export type ExplanationMode = 'ai' | 'fallback' | 'demo' | 'unknown'
export type ExplanationBlockKind = 'skill' | 'time' | 'interest' | 'limited' | 'review' | 'checks' | 'text'
export interface ExplanationBlock {
  kind: ExplanationBlockKind
  text: string
}

const modes: Record<string, ExplanationMode> = {
  'AI-selected explanation using recorded information; wording is generated by PHAROS templates.': 'ai',
  'Deterministic explanation: AI is unavailable or its response could not be used.': 'fallback',
  'Deterministic explanation: this is a fictional demo, not a real opportunity.': 'demo',
}

function blockKind(text: string): ExplanationBlockKind {
  if (text === 'One of your saved skills matches a tag recorded for this opportunity. Consider whether its content adds something to what you already know.') return 'skill'
  if (/^You saved \d+(?:\.\d+)? learning hours per week\. Compare this with the provider's workload; the record does not establish that it fits your schedule\.$/.test(text)) return 'time'
  if (/^Your saved interest in (?:AI and machine learning|web development|cybersecurity|data science|general learning) matches a topic recorded for this opportunity\. This may make it worth exploring; it does not establish eligibility\.$/.test(text)) return 'interest'
  if (text === 'The available profile and recorded topics do not establish a direct match. Compare the description with your learning goals before deciding.') return 'limited'
  if (text === 'Unreviewed: these recorded details have not completed human review.'
    || text === 'Do not apply using fictional demo information.'
    || text === 'The record is marked checked against source; this does not confirm current availability or your eligibility.') return 'review'
  if (text.startsWith('Next checks: ')) return 'checks'
  return 'text'
}

/** Presentation only: the API exposes prose, not structured explanation metadata.
 * Recognize the current templates conservatively; retain all unfamiliar wording.
 * Neither a successful HTTP request nor a mention of AI establishes AI selection.
 */
export function presentExplanation(answer: string) {
  const paragraphs = answer.split(/\r?\n\s*\r?\n/).map(text => text.trim()).filter(Boolean)
  const first = paragraphs[0] ?? ''
  const mode = Object.hasOwn(modes, first) ? modes[first] : 'unknown'
  const modeText = mode === 'unknown' ? null : paragraphs.shift()!
  const blocks: ExplanationBlock[] = paragraphs.map(text => ({ kind: blockKind(text), text }))
  return { mode, modeText, blocks }
}

/** Only turn the existing explicit checklist into items; never infer missing checks. */
export function presentChecks(text: string) {
  const match = /^(Next checks: use the source link on this page to confirm the )(current application or enrollment window), (eligibility), (learning costs versus certification fees), (deadlines) and (workload)\. (Unknown details remain unknown\. This explanation does not confirm eligibility, availability, fees or deadlines\.)$/.exec(text)
  return match ? { intro: match[1], items: match.slice(2, 7), limitation: match[7] } : null
}
